window.kbPageData["views/entry/k-e20d279329469aaa"] = {"key":"entry/k-e20d279329469aaa","state":{"route":"entry/k-e20d279329469aaa"},"node":{"id":"k-e20d279329469aaa","mode":"k","title":"长方体的面面积与棱长","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["长方体的面面积与棱长的关系"],"qs":["国考 2025 行政执法 行测#75"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"长方体一个面的面积等于该面两条相邻棱长的乘积。若三个方向的棱长依次为 a≥b≥c，则三种面的面积满足 ab≥ac≥bc。","review":{"definition":"长方体一个面的面积等于该面两条相邻棱长的乘积。若三个方向的棱长依次为 a≥b≥c，则三种面的面积满足 ab≥ac≥bc。","explanation":"本题最小面的长和宽分别为 b、c，所求是 b/c。最大面面积 ab 是最小面面积 bc 的 3 倍，因此两者的面积平均值为 2bc。次大面面积 ac 是这个平均值的 9/16，即 9bc/8。最大面和次大面共用棱长 a，面积相除即可求得 b/c＝ab/ac＝8/3，对应 C 项。","references":[],"evidence":"最大面的面积为ab、次大面的面积为ac","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 行政执法 行测#75":{"paper":"国考 2025 行政执法 行测","n":75,"mod":"数量关系","src":["d8efe4e19862104d89c8.pdf",12],"asrc":["e2c4b1970d2b49eac0fd.pdf",24],"card":"27b70bbed319511c0ad85cce","links":[{"id":"k-e20d279329469aaa","role":"解题依据","why":"面面积等于两条相邻棱长的乘积，最大面由最长和次长的棱组成，最小面由次长和最短的棱组成。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e20d279329469aaa":[["国考 2025 行政执法 行测#75"]]}};
